parameters.jsCode:
// ประกอบหนังสือตอบรับตามแบบหนังสือภายนอกอย่างย่อ ส่วนหัวและท้ายมาจากโค้ด เนื้อความมาจากโมเดล
const r = $('บันทึกการมอบหมาย').item.json;
const d = DateTime.now().setZone('Asia/Bangkok').setLocale('th');
const thaiDate = `${d.day} ${d.toFormat('MMMM')} ${d.year + 543}`;
// หนังสือราชการไทยไม่ใช้จุดท้ายประโยค โมเดลมักเติมมา จึงลบออก
const body = String($json.text || '').trim().replace(/\.(\s*\n|\s*$)/g, '$1');
const letter = [
  `ที่ บส 52001/${r.ticket_no}`,
  'สำนักงานเทศบาลเมืองบ้านสวน',
  '',
  thaiDate,
  '',
  `เรื่อง  ตอบรับเรื่อง ${r.subject}`,
  '',
  `เรียน  ${r.sender || 'ผู้แจ้งเรื่อง'}`,
  '',
  body,
  '',
  'จึงเรียนมาเพื่อโปรดทราบ',
  '',
  'ขอแสดงความนับถือ',
  '',
  '(ลงชื่อ ................................)',
  'ปลัดเทศบาล ปฏิบัติราชการแทน',
  'นายกเทศมนตรีเมืองบ้านสวน',
  '',
  'งานสารบรรณ สำนักปลัดเทศบาล โทร 0 4400 1234 ต่อ 100',
].join('\n');
return { json: { draft_reply: letter } };

